/**
 * @fileoverview Test the usage of a removed property
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-removed-property-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester({
    settings: {
        extjs: {
            toolkit: 'modern',
            fromVersion: '6.0',
            toVersion: '7.9.0'
        }
    }
});
ruleTester.run('no-removed-property-usage', rule, {

    valid: [
        {
            code: `
                Ext.Array.contains();
                Ext.getBody();
                Ext.getDoc();
                Ext.JSON.encode(data)
            `
        }
    ],

    invalid: [
        {
            code: `
                // test removed 'alignmentRegex' property in an extended class
                Ext.define('MyCustomCheckbox', {
                    extend: 'Ext.field.Checkbox',
                    initialize: function () {
                        this.alignmentRegex = /abc/;
                    }
                });

                // test removed 'alignmentRegex' property from a variable in an extended class
                Ext.define('MyCustomCheckbox', {
                    extend: 'Ext.field.Checkbox',
                    initialize: function () {
                        var me = this;
                        me.alignmentRegex = Ext.emptyFn;
                    }
                });

                // test removed 'alignmentRegex' property in an overridden class
                Ext.define('MyCustomCheckbox', {
                    override: 'Ext.field.Checkbox',
                    initialize: function () {
                        var me = this;
                        me.alignmentRegex = /abc/;
                    }
                });

                // test removed 'alignmentRegex' property as a config in an extended class
                Ext.define('MyCustomCheckbox', {
                    extend: 'Ext.field.Checkbox',
                    alignmentRegex: 2
                });

                // test removed 'alignmentRegex' property as a config in an overridden class
                Ext.define('MyCustomCheckbox', {
                    override: 'Ext.field.Checkbox',
                    alignmentRegex: Ext.emptyFn
                });
            `,
            errors: [
                { message: /Usage of removed property 'alignmentRegex' found for 'Ext.field.Checkbox'/ },
                { message: /Usage of removed property 'alignmentRegex' found for 'Ext.field.Checkbox'/ },
                { message: /Usage of removed property 'alignmentRegex' found for 'Ext.field.Checkbox'/ },
                { message: /Usage of removed property 'alignmentRegex' found for 'Ext.field.Checkbox'/ },
                { message: /Usage of removed property 'alignmentRegex' found for 'Ext.field.Checkbox'/ }
            ]
        }
    ]
});
